    'a': 1,
    'b': {
        'c': 2,
        'd': {
            'e': 3
        }
    }
}

flat_dict = flatten_dict(nested_dict)

assert isinstance(flat_dict, dict), "Result is not a dictionary"
assert len(flat_dict) == 3, f"Expected 3 flattened keys, got {len(flat_dict)}"
